insert into public.dialogue_lines (dialogue_id, locale, line_order, content, line_format) select dialogues.id, lines.locale, lines.line_order, lines.content, lines.line_format from jsonb_to_recordset($seed$[{"dialogue_key":"noun_repair_q01_finish","locale":"he","line_order":0,"content":"חזרתם! עכשיו הדפים כבר נראים הרבה יותר טוב.","line_format":"plain_text"},{"dialogue_key":"noun_repair_q01_finish","locale":"he","line_order":1,"content":"הספר שוב יודע להבדיל בין boy, table, park ו cat.","line_format":"plain_text"},{"dialogue_key":"noun_repair_q01_finish","locale":"he","line_order":2,"content":"איזה מזל שעזרתם לי. בלעדיכם הוא היה קורא לכל דבר toaster.","line_format":"plain_text"},{"dialogue_key":"noun_repair_q01_finish","locale":"he","line_order":3,"content":"ליד השער מחכה ילד שמצא עוד שמות מבולבלים.","line_format":"plain_text"},{"dialogue_key":"noun_repair_q01_finish","locale":"he","line_order":4,"content":"קחו את ה Gem אליו. אולי הסיפור שלו יעזור לנו לתקן את הספר.","line_format":"plain_text"},{"dialogue_key":"noun_repair_q01_start","locale":"he","line_order":0,"content":"אוי לא! ספר המילים שלי נפתח באמצע הלילה, ושמות העצם נעלמו מהעמודים.","line_format":"plain_text"},{"dialogue_key":"noun_repair_q01_start","locale":"he","line_order":1,"content":"עכשיו הספר מלא בתמונות בלי שמות, ואף אחד לא יודע מה הוא רואה.","line_format":"plain_text"},{"dialogue_key":"noun_repair_q01_start","locale":"he","line_order":2,"content":"אני צריכה עזרה להחזיר לספר את השמות של אנשים, מקומות, חפצים וחיות.","line_format":"plain_text"},{"dialogue_key":"noun_repair_q01_start","locale":"he","line_order":3,"content":"הדפים מחכים במקום שבו נשמרו הדברים שאבדו.","line_format":"plain_text"},{"dialogue_key":"noun_repair_q01_start","locale":"he","line_order":4,"content":"אחרי שתסיימו, חזרו אליי עם מה שמצאתם.","line_format":"plain_text"},{"dialogue_key":"noun_repair_q02_finish","locale":"he","line_order":0,"content":"יש! עכשיו התיק שלי מספר את האמת.","line_format":"plain_text"},{"dialogue_key":"noun_repair_q02_finish","locale":"he","line_order":1,"content":"ה dog כבר לא מתחבא מאחורי ה pencil, וה bag שוב נראה כמו תיק.","line_format":"plain_text"},{"dialogue_key":"noun_repair_q02_finish","locale":"he","line_order":2,"content":"קחו את ה Power Stone לחקלאי בשוק.","line_format":"plain_text"},{"dialogue_key":"noun_repair_q02_finish","locale":"he","line_order":3,"content":"הוא אמר שגם אצלו השמות התחלפו.","line_format":"plain_text"},{"dialogue_key":"noun_repair_q02_finish","locale":"he","line_order":4,"content":"אולי הפעם apple לא ינסה להתחפש ל banana.","line_format":"plain_text"},{"dialogue_key":"noun_repair_q02_start","locale":"he","line_order":0,"content":"שלום! התיק שלי חזר, אבל השמות שהיו עליו עדיין מבולבלים.","line_format":"plain_text"},{"dialogue_key":"noun_repair_q02_start","locale":"he","line_order":1,"content":"לפעמים אני מסתכל על דבר ולא יודע איך קוראים לו באנגלית.","line_format":"plain_text"},{"dialogue_key":"noun_repair_q02_start","locale":"he","line_order":2,"content":"אני רוצה שכל דבר יחזור לשם הנכון שלו.","line_format":"plain_text"},{"dialogue_key":"noun_repair_q02_start","locale":"he","line_order":3,"content":"מה שנשאר מהתיק מחכה ליד העגלה.","line_format":"plain_text"},{"dialogue_key":"noun_repair_q02_start","locale":"he","line_order":4,"content":"כשתחזרו, ספרו לי מה הצלחתם להציל.","line_format":"plain_text"},{"dialogue_key":"noun_repair_q03_finish","locale":"he","line_order":0,"content":"מצוין! עכשיו כולם יודעים ש apple הוא פרי ו bread הוא אוכל.","line_format":"plain_text"},{"dialogue_key":"noun_repair_q03_finish","locale":"he","line_order":1,"content":"הקונים שוב מוצאים את מה שחיפשו, ואף אחד לא חוזר הביתה עם hammer במקום banana.","line_format":"plain_text"},{"dialogue_key":"noun_repair_q03_finish","locale":"he","line_order":2,"content":"קחו את ה Ancient Rune לאישה הזקנה.","line_format":"plain_text"},{"dialogue_key":"noun_repair_q03_finish","locale":"he","line_order":3,"content":"במטבח שלה קרה בלבול גדול עוד יותר.","line_format":"plain_text"},{"dialogue_key":"noun_repair_q03_finish","locale":"he","line_order":4,"content":"אולי תוכלו להחזיר גם לשם קצת סדר.","line_format":"plain_text"},{"dialogue_key":"noun_repair_q03_start","locale":"he","line_order":0,"content":"ברוכים הבאים לשוק. היום הלקוחות מסתכלים על השלטים ולא מבינים מה לקנות.","line_format":"plain_text"},{"dialogue_key":"noun_repair_q03_start","locale":"he","line_order":1,"content":"פירות, אוכל וכלי עבודה קיבלו שמות לא נכונים.","line_format":"plain_text"},{"dialogue_key":"noun_repair_q03_start","locale":"he","line_order":2,"content":"אני צריך שהשוק יחזור להיות מקום פשוט וברור.","line_format":"plain_text"},{"dialogue_key":"noun_repair_q03_start","locale":"he","line_order":3,"content":"הדברים שמחכים לתיקון נמצאים ליד הדוכן.","line_format":"plain_text"},{"dialogue_key":"noun_repair_q03_start","locale":"he","line_order":4,"content":"אחרי שתעזרו לי, חזרו עם החדשות.","line_format":"plain_text"},{"dialogue_key":"noun_repair_q04_finish","locale":"he","line_order":0,"content":"איזה יופי! עכשיו ה chef מבשל, ה spoon מערבב וה plate נח בשקט.","line_format":"plain_text"},{"dialogue_key":"noun_repair_q04_finish","locale":"he","line_order":1,"content":"המטבח שוב מרגיש כמו בית.","line_format":"plain_text"},{"dialogue_key":"noun_repair_q04_finish","locale":"he","line_order":2,"content":"קחו את ה Gem לפרופסור המשוגע.","line_format":"plain_text"},{"dialogue_key":"noun_repair_q04_finish","locale":"he","line_order":3,"content":"הוא אחראי לבלגן הבא, אבל אולי יש לו הסבר טוב.","line_format":"plain_text"},{"dialogue_key":"noun_repair_q04_finish","locale":"he","line_order":4,"content":"רק תיזהרו. המדע שלו אוהב הפתעות.","line_format":"plain_text"},{"dialogue_key":"noun_repair_q04_start","locale":"he","line_order":0,"content":"אוי, איזה בלגן! במטבח שלי כל השמות קפצו ממקום למקום.","line_format":"plain_text"},{"dialogue_key":"noun_repair_q04_start","locale":"he","line_order":1,"content":"ה spoon מתנהג כאילו הוא הטבח, וה plate מחלק פקודות.","line_format":"plain_text"},{"dialogue_key":"noun_repair_q04_start","locale":"he","line_order":2,"content":"אפילו האנשים במטבח כבר לא בטוחים איך קוראים להם.","line_format":"plain_text"},{"dialogue_key":"noun_repair_q04_start","locale":"he","line_order":3,"content":"אני רק רוצה שהמטבח יחזור להיות שקט ונעים.","line_format":"plain_text"},{"dialogue_key":"noun_repair_q04_start","locale":"he","line_order":4,"content":"כשתסיימו, חזרו אליי. יהיה לי משהו בשבילכם.","line_format":"plain_text"},{"dialogue_key":"noun_repair_q05_finish","locale":"he","line_order":0,"content":"נפלא! ה queen שוב יושבת על ה throne, וה crown חזר לראש.","line_format":"plain_text"},{"dialogue_key":"noun_repair_q05_finish","locale":"he","line_order":1,"content":"אפילו ה guard יודע עכשיו מי הוא.","line_format":"plain_text"},{"dialogue_key":"noun_repair_q05_finish","locale":"he","line_order":2,"content":"קחו את ה Power Stone למאיה.","line_format":"plain_text"},{"dialogue_key":"noun_repair_q05_finish","locale":"he","line_order":3,"content":"היא שמרה את הדף האחרון של הספר.","line_format":"plain_text"},{"dialogue_key":"noun_repair_q05_finish","locale":"he","line_order":4,"content":"נראה אם הספר מוכן להיפתח מחדש.","line_format":"plain_text"},{"dialogue_key":"noun_repair_q05_start","locale":"he","line_order":0,"content":"הניסוי שלי הצליח כמעט לגמרי. רק השמות בארמון עפו לכל הכיוונים.","line_format":"plain_text"},{"dialogue_key":"noun_repair_q05_start","locale":"he","line_order":1,"content":"עכשיו castle, tower, throne ו crown כבר לא יודעים מי הם.","line_format":"plain_text"},{"dialogue_key":"noun_repair_q05_start","locale":"he","line_order":2,"content":"אם נחזיר לכל מקום ולכל תפקיד את השם הנכון, הארמון יחזור לעצמו.","line_format":"plain_text"},{"dialogue_key":"noun_repair_q05_start","locale":"he","line_order":3,"content":"השארתי את הדברים שצריכים עזרה במקום שבו עובדים על הסימנים.","line_format":"plain_text"},{"dialogue_key":"noun_repair_q05_start","locale":"he","line_order":4,"content":"אחרי שתסיימו, חזרו אליי עם ה Power Stone.","line_format":"plain_text"},{"dialogue_key":"noun_repair_q06_finish","locale":"he","line_order":0,"content":"וואו! הספר נפתח, וכל השמות חזרו למקום שלהם.","line_format":"plain_text"},{"dialogue_key":"noun_repair_q06_finish","locale":"he","line_order":1,"content":"עכשיו אתם יודעים לזהות noun, לאיית אותו ולקרוא אותו באנגלית.","line_format":"plain_text"},{"dialogue_key":"noun_repair_q06_finish","locale":"he","line_order":2,"content":"ה cat קיבל שם, ה table הפסיק לבקש כתר, והחנות יכולה להיפתח.","line_format":"plain_text"},{"dialogue_key":"noun_repair_q06_finish","locale":"he","line_order":3,"content":"תודה רבה, גיבורי המילים.","line_format":"plain_text"},{"dialogue_key":"noun_repair_q06_finish","locale":"he","line_order":4,"content":"קחו את הפרס, ורק תיזהרו מה toaster.","line_format":"plain_text"},{"dialogue_key":"noun_repair_q06_start","locale":"he","line_order":0,"content":"חזרתם בדיוק בזמן. כל חלקי הספר נמצאים כאן.","line_format":"plain_text"},{"dialogue_key":"noun_repair_q06_start","locale":"he","line_order":1,"content":"הספר רוצה להכיר אתכם לפני שייפתח שוב בפני כל הילדים.","line_format":"plain_text"},{"dialogue_key":"noun_repair_q06_start","locale":"he","line_order":2,"content":"הוא יעבור איתכם על שמות של אנשים, חפצים, מקומות וחיות.","line_format":"plain_text"},{"dialogue_key":"noun_repair_q06_start","locale":"he","line_order":3,"content":"אחרי שתסיימו, חזרו אליי. ואז נוכל לפתוח מחדש את החנות.","line_format":"plain_text"},{"dialogue_key":"noun_repair_q06_start","locale":"he","line_order":4,"content":"אני מאמינה בכם. אתם כבר צוות תיקון מצוין.","line_format":"plain_text"}]$seed$::jsonb) as lines(dialogue_key text, locale text, line_order integer, content text, line_format text) join public.dialogues on dialogues.key = lines.dialogue_key on conflict (dialogue_id, locale, line_order) do update set content = excluded.content, line_format = excluded.line_format;
